-- Сид биллинга для стенда. Сгенерирован services/billing/seed/build-stand-seed.py.
-- Продавцы и кабинеты взяты из reference/stand-seed/seed-stand.sql потока 0:
--   22 продавцов, 22 кабинетов WB, те же идентификаторы.
-- Секретов нет: secret_ref — заведомые заглушки стенда, токенов биллинг не хранит.

BEGIN;

-- === Дерево партнёров ===
-- user_id — тот же пользователь, которому identity выдаёт роль на ветку.
ON CONFLICT (id) DO UPDATE SET user_id = COALESCE(partner.user_id, EXCLUDED.user_id);

-- === Кабинеты ===
-- cabinet.wms_owner_id — тот же uuid владельца, что в базе wms: события
-- физического действия несут его, а не внешний ключ продавца.
ON CONFLICT (seller_external_id) DO NOTHING;

-- === Кабинеты Wildberries ===
-- У двух владельцев их по два — поэтому отдельная таблица, а не поле.
ON CONFLICT (external_id) DO NOTHING;

-- === Закрепление кабинетов за менеджерами ===
-- Раскладка по трём менеджерам синтетическая: кто из реальных менеджеров
-- ведёт какой кабинет, знает владелец, и на стенде этих данных нет и быть
-- не должно. История закреплений от этого не страдает — важна её форма.
ON CONFLICT (id) DO NOTHING;

-- === Наценка партнёра ===
-- 15 ₽ с операции у старшего менеджера (раздел 1 мастера).
-- У менеджеров кабинетов своей наценки нет — допущение раздела 13, вопрос 6.
-- Выражено отсутствием строки, а не нулём: ноль читался бы как решение.
--
-- Хранения в списке нет намеренно: мастер говорит «наценка 15 ₽ с операции»,
-- а коробко-место × сутки — не операция. Ставит ли партнёр наценку на
-- хранение, знает владелец (продолжение раздела 13, вопрос 5). До ответа
-- хранение тарифицируется без наценки, и это видно в расшифровке счёта.
ON CONFLICT (id) DO NOTHING;

-- === Тарифы на все услуги ===
-- Цены — заглушки: раздел 13, вопрос 3 («список услуг с ценами») владельцем
-- не закрыт, и допущение того же вопроса разрешает строить биллинг на них
-- с правкой в админке. Заглушкой не является только 30 ₽ за операцию —
-- это тариф MM-Express из раздела 1, и вместе с наценкой партнёра он даёт
-- те самые 45 ₽, которые платит клиент.
ON CONFLICT (code) DO NOTHING;

-- partner_fee — ставка последней надежды для кабинета, которому слой
-- наценки ещё не завели (так наценка жила в биллинге as-is, раздел 2.10).
-- У хранения она ноль, и это решение, а не забывчивость: мастер говорит
-- «15 ₽ с операции», а коробко-место × сутки — не операция. Оставить здесь
-- 15 значило бы протащить наценку на хранение через запасной путь, ровно
-- мимо решения не ставить её до ответа владельца.
                                    approved_by, approved_at, partner_fee) VALUES
    ('392e742c-4e2b-5cca-a202-5c0927f926cf', 'a8b28161-57f9-5ff8-8b4e-91be8efb52ee', DATE '2026-01-01', true, 'стенд: заглушка вместо подписи владельца', now(), 15.00),
    ('b3d06b28-7dbc-5e52-bd13-805ef7fffcef', '5bf08aa9-1576-53ae-b8c1-7f8fbff01716', DATE '2026-01-01', true, 'стенд: заглушка вместо подписи владельца', now(), 0.00),
    ('277cb8c8-e009-5e09-92f3-39c0b1fbac5f', 'b25876d7-ae34-5284-b6e5-db96aeb90d2f', DATE '2026-01-01', true, 'стенд: заглушка вместо подписи владельца', now(), 15.00),
    ('6f9e8315-1796-573e-a309-9bce0111867f', 'f11de5fd-a87f-5d58-a393-77ffe1a133c5', DATE '2026-01-01', true, 'стенд: заглушка вместо подписи владельца', now(), 15.00),
    ('d7431fb9-628d-50e5-8492-56f68a646079', 'd44174d6-0edc-5db2-83bb-e7bb3d1b05a9', DATE '2026-01-01', true, 'стенд: заглушка вместо подписи владельца', now(), 15.00),
    ('58dc96b4-e539-5363-9a68-3410959747c3', '6171e389-5cb7-534e-9a9a-08b3efab104b', DATE '2026-01-01', true, 'стенд: заглушка вместо подписи владельца', now(), 15.00),
    ('0d2c2142-1f40-5dd1-b08a-f415d540f672', '3de3129e-0591-5f95-93d7-69ff57ae996d', DATE '2026-01-01', true, 'стенд: заглушка вместо подписи владельца', now(), 15.00),
    ('ea93cdfb-e766-57d5-a25c-6bc227321acf', '1a965118-49fd-5627-a387-c9557144eea0', DATE '2026-01-01', true, 'стенд: заглушка вместо подписи владельца', now(), 15.00)
-- Ставку обновляем: повторный сид — обновление стенда, а не откат решения.
ON CONFLICT (id) DO UPDATE SET partner_fee = EXCLUDED.partner_fee;

-- Одна ступень «и далее»: объёмных скидок владелец не называл.
ON CONFLICT (id) DO NOTHING;

-- === Что тарифицируется ===
-- Список данными, а не цепочкой if'ов: сегодня на проде тарифицируются
-- четыре источника из десятков, и увидеть это можно только чтением кода.
ON CONFLICT (event_type) DO NOTHING;

COMMIT;
